import collections, json, os, pathlib, subprocess
import pytest
counts=collections.Counter(); roots=set(); labels=set()
_original_popen=subprocess.Popen

def pytest_configure(config):
    if not hasattr(config, 'workerinput'): return
    def counted(args, *a, **kw):
        if isinstance(args, (list, tuple)) and args:
            parts=list(map(str,args)); exe=pathlib.Path(parts[0]).name
            if exe=='git':
                counts['git']+=1
                for op in ('init','commit','worktree'):
                    if op in parts: counts['git_'+op]+=1
                if 'worktree' in parts:
                    for action in ('add','repair'):
                        if action in parts: counts['git_worktree_'+action]+=1
            if '-m' in parts:
                module=parts[parts.index('-m')+1]
                if module in ('parent','board'): counts[module+'_cli']+=1
            if any('review' in p and p.endswith('.py') for p in parts[:2]): counts['review_cli']+=1
        return _original_popen(args,*a,**kw)
    subprocess.Popen=counted

@pytest.hookimpl(wrapper=True)
def pytest_fixture_setup(fixturedef, request):
    value=yield
    if fixturedef.argname=='parent_env':
        roots.add(value.root)
        dest=pathlib.Path(os.environ['AGENTS_COST_DIR']);dest.mkdir(parents=True,exist_ok=True)
        real_calls=dest/('real-gh-'+os.environ['PYTEST_XDIST_WORKER']+'.jsonl')
        gh=value.root/'bin/gh'
        source=gh.read_text()
        needle='args = sys.argv[1:]'
        assert source.count(needle)==1
        gh.write_text(source.replace(needle,needle+"\nwith open("+repr(str(real_calls))+", 'a') as cost_stream: cost_stream.write(json.dumps(args)+'\\n')"))
    if fixturedef.argname=='labels': labels.add(value.state)
    if fixturedef.argname in ('parent_env','review_env','gate_env','world','labels','d'):
        counts['fixture_'+fixturedef.argname]+=1
    return value

def pytest_sessionfinish(session, exitstatus):
    if not hasattr(session.config,'workerinput'): return
    dest=pathlib.Path(os.environ['AGENTS_COST_DIR'])
    counts['fake_github_journal_rows']=sum(len((p/'calls.jsonl').read_text().splitlines()) for p in roots)
    real_calls=dest/('real-gh-'+os.environ['PYTEST_XDIST_WORKER']+'.jsonl')
    counts['fake_github']=len(real_calls.read_text().splitlines()) if real_calls.exists() else 0
    counts['fake_herdr']=sum(len(json.loads(p.read_text())['calls']) for p in labels)
    dest=pathlib.Path(os.environ['AGENTS_COST_DIR']); dest.mkdir(parents=True,exist_ok=True)
    (dest/(os.environ['PYTEST_XDIST_WORKER']+'.json')).write_text(json.dumps(counts,indent=2))

