import os, pathlib, sys
import pytest

@pytest.hookimpl(wrapper=True)
def pytest_fixture_setup(fixturedef, request):
    value=yield
    if fixturedef.argname=='parent_env' and os.environ.get('AGENTS_MUTATION') in ('accept_draft','ignore_cancellation'):
        value.env['PYTHONPATH']='/tmp/agents-defects'+os.pathsep+value.env['PYTHONPATH']
    return value

def pytest_collection_modifyitems(config,items):
    if os.environ.get('AGENTS_MUTATION')=='code_mentions':
        sys.path.insert(0,str(pathlib.Path.cwd()/'.agents/ops'))
        import board.messages
        def without_code(body):
            with open(os.environ["AGENTS_MUTATION_LOG"],"a") as stream:stream.write("code_mentions\n")
            return body
        board.messages.without_code=without_code

