import os, sys
if os.environ.get('PARENT_GH_STATE'):
    kind=os.environ.get('AGENTS_MUTATION')
    def applied():
        with open(os.environ['AGENTS_MUTATION_LOG'],'a') as f: f.write(kind+'\n')
    if kind=='accept_draft':
        import parent.policy
        original=parent.policy.select_prs
        def select(selected, prs, children, repo):
            if any(p.get('draft') is True for p in prs): applied()
            return original(selected,[{**p,'draft':False} for p in prs],children,repo)
        parent.policy.select_prs=select
    elif kind=='ignore_cancellation' and '-m' in sys.orig_argv and 'parent' in sys.orig_argv and 'workflow-report' in sys.orig_argv:
        import parent.development
        def ignore(*args,**kwargs): applied()
        parent.development.verify_cancellation=ignore
